def find_leaks(
    knowledge: Knowledge, cases: Iterable[Case], *, min_chars: int = LEAK_MIN_CHARS
) -> list[Leak]:
    """`knowledge` 的文本中，有连续 `min_chars` 个字符（NFKC、去空白后）与样本相同的条目：

