    """
    segments: dict[str, set[str]] = {}
    named = [
        *((f"{_file_of(entry)}:{entry.id}", entry.model_dump()) for entry in knowledge.entries()),
        (STYLE_GUIDE_FILE, knowledge.style_guide.model_dump()),
    ]
    for source, dumped in named:
